import tempfile,subprocess,os,pathlib
d=tempfile.mkdtemp(); h=tempfile.mkdtemp()
s=r'''
set -u
mkdir -p work
q() { \"\$@\" >/dev/null 2>&1; echo \$?; }
first() { grep -m1 -E '^(fatal|remote|error):' work/err | sed -E 's#https?://[^ ]*#<url>#g'; }
qp() { \"\$@\" >/dev/null 2>work/err; r=\$?; if [ \$r = 0 ]; then echo 0; elif grep -q -i -E '(403|denied|not allowed|permission|write access)' work/err; then echo \"\$r write-denied (\$(first))\"; else echo \"\$r other (\$(first))\"; fi; }
mk() { git -C \"\$1\" checkout -q -b \"\$2\" && echo probe > \"\$1/p.txt\" && git -C \"\$1\" add p.txt && git -C \"\$1\" commit -q -m probe; }
git config --global user.name r; git config --global user.email r@example.invalid
echo q-ok=\$(q true) q-fail=\$(q false)
echo qp-ok=\$(qp true)
echo qp-denied=\$(qp sh -c 'echo \"remote: Permission to x denied to y.\" >&2; echo \"fatal: unable to access https://h/x: The requested URL returned error: 403\" >&2; exit 128')
echo qp-other=\$(qp sh -c 'echo \"fatal: unable to connect\" >&2; exit 128')
git init -q --bare bare; git clone -q bare c 2>/dev/null; git -C c -c user.name=r -c user.email=r@e commit -q --allow-empty -m init
echo mk=\$(q mk c b1)
echo mk-again-fail=\$(q mk c b1)
echo push=\$(qp git -C c push -q origin b1)
echo push-nonexist=\$(qp git -C c push -q nonexist b1)
'''
pathlib.Path(d,'t.sh').write_text(s.replace('\\\\\$','\$'))
r=subprocess.run(['bash','t.sh'],cwd=d,env={'PATH':os.environ['PATH'],'HOME':h},text=True,capture_output=True)
print(r.stdout,r.stderr,r.returncode)
"

